name: vanessa
email: vanessa.rodrigues@esign.co.uk
Message: I'm trying to deploy a CMS application (Strapi) on Heroku. This application is connected to my MySQL database hosted on AWS. Since Heroku uses dynamic IPs, I used QuotaGuard to create a static IP. The static IPs already have access allowed to the database.

When I run the application locally, I can connect to the database normally. But when I try to deploy it on Heroku, I'm encountering some errors. Could you help me?

Below is my configuration file and the Heroku logs.


const { URL } = require('url');

module.exports = ({ env }) => {
  const client = env('DATABASE_CLIENT', 'mysql');

  const proxyUrl = env('QUOTAGUARDSTATIC_URL');
  const parsedProxyUrl = proxyUrl ? new URL(proxyUrl) : null;

  const connections = {
    mysql: {
      connection: {
        host: env('DATABASE_HOST', 'localhost'),
        port: env.int('DATABASE_PORT', 3306),
        database: env('DATABASE_NAME', 'strapi'),
        user: env('DATABASE_USERNAME', 'strapi'),
        password: env('DATABASE_PASSWORD', 'strapi'),
        ssl: env.bool('DATABASE_SSL', false) && {
          key: env('DATABASE_SSL_KEY', undefined),
          cert: env('DATABASE_SSL_CERT', undefined),
          ca: env('DATABASE_SSL_CA', undefined),
          capath: env('DATABASE_SSL_CAPATH', undefined),
          cipher: env('DATABASE_SSL_CIPHER', undefined),
          rejectUnauthorized: env.bool(
            'DATABASE_SSL_REJECT_UNAUTHORIZED',
            true
          ),
        },
        options: {
          proxy: parsedProxyUrl ? {
            host: parsedProxyUrl.hostname,
            port: parsedProxyUrl.port,
            protocol: parsedProxyUrl.protocol.replace(':', ''), 
            auth: parsedProxyUrl.username && parsedProxyUrl.password ? `${parsedProxyUrl.username}:${parsedProxyUrl.password}` : undefined,
          } : undefined,
        }
      },
      pool: { min: env.int('DATABASE_POOL_MIN', 2), max: env.int('DATABASE_POOL_MAX', 10) },
    }
  };

  return {
    connection: {
      client,
      ...connections[client],
      acquireConnectionTimeout: env.int('DATABASE_CONNECTION_TIMEOUT', 60000),
    },
  };
};


2024-07-09T12:15:56.161398+00:00 app[web.1]: [2024-07-09 12:15:56.159] debug: ⛔️ Server wasn't able to start properly.
